<?php
declare(strict_types=1);
final class CatalogService {
    public function __construct(private PDO $db) {}
    private function base(): string { return "FROM perfumes p LEFT JOIN brands b ON b.id=p.brand_id LEFT JOIN categories c ON c.id=p.category_id WHERE p.status='publicado' AND p.is_published=1 AND p.deleted_at IS NULL AND (b.id IS NULL OR (b.is_active=1 AND b.deleted_at IS NULL)) AND (c.id IS NULL OR (c.is_active=1 AND c.deleted_at IS NULL))"; }
    public function published(int $page=1,int $perPage=12,array $filters=[]): array { $page=max(1,$page);$perPage=min(60,max(1,$perPage));$where=$this->base();$values=[];if(!empty($filters['gender'])){$where.=' AND p.gender=?';$values[]=$filters['gender'];}if(!empty($filters['brand_id'])){$where.=' AND p.brand_id=?';$values[]=(int)$filters['brand_id'];}if(!empty($filters['category_id'])){$where.=' AND p.category_id=?';$values[]=(int)$filters['category_id'];}if(!empty($filters['q'])){$where.=' AND (p.name LIKE ? OR EXISTS(SELECT 1 FROM perfume_aliases pa WHERE pa.perfume_id=p.id AND pa.normalized_alias LIKE ?))';$q='%'.$filters['q'].'%';$values[]=$q;$values[]=$q;}$count=$this->db->prepare("SELECT COUNT(*) {$where}");$count->execute($values);$total=(int)$count->fetchColumn();$sql="SELECT p.*,b.name brand_name,c.name category_name {$where} ORDER BY p.sort_order,p.name LIMIT {$perPage} OFFSET ".(($page-1)*$perPage);$s=$this->db->prepare($sql);$s->execute($values);return ['items'=>$s->fetchAll(),'total'=>$total,'page'=>$page,'per_page'=>$perPage,'pages'=>$total?(int)ceil($total/$perPage):0]; }
    public function featured(int $limit=8): array { $s=$this->db->prepare("SELECT p.*,b.name brand_name,c.name category_name FROM perfumes p LEFT JOIN brands b ON b.id=p.brand_id LEFT JOIN categories c ON c.id=p.category_id WHERE p.status='publicado' AND p.is_published=1 AND p.is_featured=1 AND p.deleted_at IS NULL AND (b.id IS NULL OR (b.is_active=1 AND b.deleted_at IS NULL)) AND (c.id IS NULL OR (c.is_active=1 AND c.deleted_at IS NULL)) ORDER BY p.sort_order,p.name LIMIT ?");$s->bindValue(1,max(1,$limit),PDO::PARAM_INT);$s->execute();return $s->fetchAll(); }
}
